public sealed class EmailQueue                       // один на приложение: singleton
{
    private readonly Channel<string> _ch = Channel.CreateBounded<string>(1000);
    public ValueTask EnqueueAsync(string to, CancellationToken ct) => _ch.Writer.WriteAsync(to, ct);
    public IAsyncEnumerable<string> ReadAllAsync(CancellationToken ct) => _ch.Reader.ReadAllAsync(ct);
}

